// ─────────────────────────────────────────────────────────────────────────────
// Los datos de esta página no se editan a mano.
// Los arma `npm run actualizar` (scripts/actualizar.mjs + scripts/armar.mjs)
// a partir de datos/catalogo.json, datos/mercado.json y datos/noticias.json,
// y los pega en el bloque @@DATOS-INICIO / @@DATOS-FIN de más abajo.
// ─────────────────────────────────────────────────────────────────────────────

type Pt = { d: string; v: number };

type Quote = {
  name: string;
  price: number;
  chg: number;
  dayChg: number;
  open: number;
  high: number;
  low: number;
  hi52: number;
  lo52: number;
  m1: number | null;
  m3: number | null;
  pts: Pt[];
  ccy?: "USD" | "AUD";
  asOf: string;
};

type Ccy = "USD" | "ARS" | "AUD";
type BaKind = "local" | "cedear";
type BaQuote = { symbol: string; name: string; kind: BaKind; price: number; chg: number; dayChg: number; asOf?: string };
/** fx: dólar MEP (venta) del día de compra que cargó la persona. Si falta, se busca en la historia por fecha. */
type Lot = { id: string; ticker: string; qty: number; price: number; date: string; ccy: Ccy; fx?: number };
type PersistMode = "loading" | "local" | "memory";
type HeatWindow = "d" | "m1" | "m3";
type MainTab = "calor" | "cartera" | "divs" | "mercado" | "analisis" | "datos" | "info";

type DivRow = {
  ttm: number;
  n12: number | null;
  lastEx: string | null;
  lastAmt: number | null;
  lastPay: string | null;
  nextEx: string | null;
  nextPay: string | null;
  hist: [string, number][];
  partial?: boolean;
};
type Earn = { date: string; estimate: boolean };
type IndexRow = {
  id: string;
  label: string;
  kind: "indice" | "tasa" | "usd" | "fx";
  level: number;
  chg: number | null;
  chgAbs: number | null;
  m1: number | null;
  m3: number | null;
  m1Abs?: number | null;
  m3Abs?: number | null;
  asOf?: string;
};
type Pair = { compra: number; venta: number };
type NewsLink = { title: string; site: string; date: string; href: string };
type TickerNote = { date: string; text: string; news: NewsLink[] };
type CalEvent = { date: string; ticker: string; title: string; detail: string; src: string };

type Dataset = {
  v: 2;
  generatedAt: string;
  sessions: { ny?: string; asx?: string; ba?: string; fx?: string };
  fx: { mep: Pair; ccl: Pair | null; oficial: Pair | null; blue: Pair | null; audusd: number; audusdChg: number | null };
  mepHist: [string, number][];
  watchDefault: string[];
  order: string[];
  aliases: Record<string, string[]>;
  catalog: Record<string, Quote>;
  ba: Record<string, BaQuote>;
  div: Record<string, DivRow>;
  earnings: Record<string, Earn>;
  indices: IndexRow[];
  notes: {
    updatedAt: string | null;
    market: string;
    tickers: Record<string, TickerNote>;
    calendar: CalEvent[];
    divNotes: Record<string, string>;
  };
};

